// DFS 回溯：走過的格子暫時改成 '#'，回溯時還原
// 時間複雜度: O(m·n·3^L)，空間複雜度: O(L)
function exist(board, word) {
    const m = board.length, n = board[0].length;
    const dfs = (i, j, k) => {
        if (k === word.length)
            return true;
        if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] !== word[k])
            return false;
        const ch = board[i][j];
        board[i][j] = '#';
        const found = dfs(i + 1, j, k + 1) || dfs(i - 1, j, k + 1)
            || dfs(i, j + 1, k + 1) || dfs(i, j - 1, k + 1);
        board[i][j] = ch;
        return found;
    };
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (dfs(i, j, 0))
                return true;
        }
    }
    return false;
}

