// DFS 回溯：走過的格子暫時改成 '#'，回溯時還原
// 時間複雜度: O(m·n·3^L)，空間複雜度: O(L)
static bool dfs(char** board, int m, int n, int i, int j, const char* word) {
    if (*word == '\0') return true;
    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != *word) return false;
    char ch = board[i][j];
    board[i][j] = '#';
    bool found = dfs(board, m, n, i + 1, j, word + 1) || dfs(board, m, n, i - 1, j, word + 1)
              || dfs(board, m, n, i, j + 1, word + 1) || dfs(board, m, n, i, j - 1, word + 1);
    board[i][j] = ch;
    return found;
}

bool exist(char** board, int boardSize, int* boardColSize, char* word) {
    int m = boardSize, n = boardColSize[0];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (dfs(board, m, n, i, j, word)) return true;
        }
    }
    return false;
}
